  const explicitDiscoveryEntityId = input.contextAction?.type === 'open_discovery_entity' && input.contextAction.entityId ? String(input.contextAction.entityId) : undefined; const explicitDiscoveryEntity = explicitDiscoveryEntityId ? await getDiscoveryEntity(explicitDiscoveryEntityId) : null; const continuationAction = input.contextAction?.type === 'resume_canonical_context' ? input.contextAction : null; const allowedContinuationPairs = CANONICAL_CONTEXT_ACTIONS; let continuationObject: any = null; const continuationPair = continuationAction?.objectType && continuationAction.canonicalAction ? `${continuationAction.objectType}:${continuationAction.canonicalAction}` : '';
  if (emergency) { reply = emergency.reply; cardData = emergency.cardData; canonicalAction = emergency.canonicalAction; progressStage = 'safety'; classificationSource = 'rules'; intentConfidence = 1; extractionSource = 'deterministic'; extractedEntities = { emergencyService: emergency.session?.serviceType, emergencyDialState: emergency.session?.dialState }; }
  else if (interactionPolicy.kind === 'security') { reply = 'I’m treating this as a security interruption. Do not share OTPs, passwords, recovery codes, or payment details. If your phone was stolen, use your mobile operator and device account controls to block the SIM and secure the device; if you do not recognize a payment, contact the payment provider through its verified channel. I can help you prepare the next steps, but I have not changed account ownership, issued a refund, cancelled a payment, or claimed recovery. Those actions require authenticated ownership and explicit confirmation.'; cardData = { type: 'security_interruption', status: 'assessment', canonicalAction: 'security.assess', requiresAuthenticationForMutation: true, requiresExplicitConfirmation: true, truthful: true, nextActions: [{ id: 'secure_device', label: 'Secure device and SIM' }, { id: 'review_account', label: 'Review account access' }, { id: 'contact_provider', label: 'Contact verified provider' }] }; canonicalAction = 'security.assess'; progressStage = 'safety'; classificationSource = 'rules'; intentConfidence = 1; extractionSource = 'deterministic'; }
  else if (asksForBrief) { const brief = await buildAgentBrief(phone); reply = brief.presentation.text; cardData = { type: 'agent_brief', briefId: brief.id, presence: brief.presence, items: brief.items.map(item => ({ stableRef: item.stableRef, category: item.category, priority: item.priority, urgency: item.urgency, summary: item.summary, action: item.action, approvalRequired: item.approvalRequired, attention: item.attention })), deterministic: true, existingOwners: true, requiresExplicitConfirmationForActions: true }; canonicalAction = 'agent.brief.review'; progressStage = 'information'; classificationSource = 'rules'; intentConfidence = 1; extractionSource = 'deterministic'; }
  else if (asksToDealWithFirst) { const brief = await buildAgentBrief(phone); const selected = await continueFirstBriefItem(phone, brief); if (selected) { reply = selected.reply; cardData = selected.cardData; canonicalAction = selected.canonicalAction; progressStage = selected.progressStage; classificationSource = 'rules'; intentConfidence = 1; extractionSource = 'deterministic'; } else { reply = brief.items.length ? `I found the first item, but its exact continuation is no longer available. I have not substituted another request or action. ${brief.presentation.text}` : 'There is nothing actionable waiting for you right now.'; cardData = { type: 'agent_brief', briefId: brief.id, items: brief.items, exactContext: false }; canonicalAction = 'agent.brief.first_item.unavailable'; progressStage = 'information'; classificationSource = 'rules'; intentConfidence = 1; extractionSource = 'deterministic'; } }
  else if (continuationAction && !isGuest && continuationPair && allowedContinuationPairs.has(continuationPair) && continuationAction.objectType && continuationAction.objectId) { if (continuationAction.objectType === 'agent_goal') continuationObject = await getAgentGoal(phone, continuationAction.objectId); else if (continuationAction.objectType === 'economic_request') { const request = await getEconomicRequest(continuationAction.objectId); continuationObject = request && request.phone === phone ? request : null; } else if (continuationAction.objectType === 'discovery_entity') continuationObject = await getDiscoveryEntity(continuationAction.objectId); else if (continuationAction.objectType === 'contact') { try { continuationObject = await getPersonProfile(phone, continuationAction.objectId, 'message'); } catch { continuationObject = null; } } else if (continuationAction.objectType === 'reminder') continuationObject = await getReminderForPhone(phone, continuationAction.objectId); else if (continuationAction.objectType === 'memory_context') { const factId = Number(continuationAction.objectId); continuationObject = Number.isSafeInteger(factId) && factId > 0 ? (await getMemoryFacts(phone)).find(fact => fact.id === factId) || null : null; } else if (continuationAction.objectType === 'task') { const taskId = Number(continuationAction.objectId); continuationObject = Number.isSafeInteger(taskId) ? await getAssignedTask(phone, taskId) : null; } else if (continuationAction.objectType === 'notification') { const notificationId = Number(continuationAction.objectId); continuationObject = Number.isSafeInteger(notificationId) && notificationId > 0 ? await getInternalNotificationById(notificationId, phone) : null; } }
  const recognizedCompoundObjective = !isGuest && Boolean(recognizeCompoundObjective(message));
  const contextDecision = isGuest ? undefined : await arbitrateChatContext({ phone, message, conversationId: input.conversationId });
